Import ListNotations.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Open Scope bv_scope.

Ltac Zify.zify_convert_to_euclidean_division_equations_flag ::= constr:(false).

#[local] Abbreviation ASEGS := AsanUbsan.M.loaded_segments.

Definition SB : Z := ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00!1,0|N3fff8000;").
Definition LOWEND : Z := ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00!1,0|N3fff7fff;").         (* [comment removed for export] *)
Definition HIGHBEG : Z := 0x10007fff8000.    (* [comment removed for export] *)
Definition HIGHEND : Z := 0x7fffffffffff.    (* [comment removed for export] *)

Section FPX_1. Context {fx : PropExec.FPState}.

(* [comment removed for export] *)
Definition rt_layout_globs (M : word -> option byte) : Prop :=
  rdn ASEGS M (0x164518 : word) 8%nat = Some (word_to_le_bytes 8 (Z_to_bv 64 0x16d7b8)) /\
  rdn ASEGS M (0x16d7b8 : word) 8%nat = Some (word_to_le_bytes 8 (Z_to_bv 64 SB)) /\
  rdn ASEGS M (0x164520 : word) 8%nat = Some (word_to_le_bytes 8 (Z_to_bv 64 0x16e4a8)) /\
  rdn ASEGS M (0x16e4a8 : word) 8%nat = Some (word_to_le_bytes 8 (Z_to_bv 64 0)) /\
  rdn ASEGS M (0x164528 : word) 8%nat = Some (word_to_le_bytes 8 (Z_to_bv 64 0x16e4b0)) /\
  rdn ASEGS M (0x16e4b0 : word) 8%nat = Some (word_to_le_bytes 8 (Z_to_bv 64 0)) /\
  rdn ASEGS M (0x164530 : word) 8%nat = Some (word_to_le_bytes 8 (Z_to_bv 64 0x16e4a0)) /\
  rdn ASEGS M (0x16e4a0 : word) 8%nat = Some (word_to_le_bytes 8 (Z_to_bv 64 HIGHEND)).

Definition in_app (p : Z) : Prop := ltac2:(Rpl.RP.run_i (rplG ()) 1 "S00$p;R+1!2+2!2+3!2'4,5#1!2'4#1'6!2+3!2'4'7#1!2'4#1'8").

#[local] Ltac rwH :=
  repeat match goal with
         | H : getr ?rg ?i = _ |- context [getr ?rg ?i] => rewrite !H
         end.
#[local] Ltac unorm :=
  repeat match goal with
         | |- context [bv_unsigned (Z_to_bv 64 ?z)] =>
             lazymatch z with context [Z_to_bv 64 _] => fail | _ => rewrite (u_Z2bv z) by lia end
         end.
#[local] Ltac cond :=
  rwH; unfold at_, v_addi, v_add, c_eq, c_ltu, bv_eqb, bv_ltu; imm_norm; unorm;
  first [apply Z.eqb_eq | apply Z.eqb_neq | apply Z.ltb_lt | apply Z.ltb_ge]; lia.
#[local] Ltac wval :=
  gres; rwH; unfold at_, v_addi, v_add, v_sub, v_srli; imm_norm; unorm; rewrite ?Z.shiftr_div_pow2 by lia;
  try change (2 ^ 3)%Z with 8%Z; first [reflexivity | f_equal; lia].

(* [comment removed for export] *)
(* [comment removed for export] *)
(* [comment removed for export] *)
Lemma memtoshadow_run : forall regs (M rom : word -> option byte) (ret : word) (p : Z),
  rt_layout_globs M -> in_app p ->
  getr regs 10 = Z_to_bv 64 p -> getr regs 1 = ret -> ret_ok ret ->
  exists regs',
