Definition keeps_but (L : list reg) (regs regs' : bvmap 5 word) : Prop :=
  forall r : reg, In r callee_saved -> ~ In r L -> getr regs' r = getr regs r.
Lemma keeps_but_refl : forall L regs, keeps_but L regs regs.  Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S30!1,:|21;!1+;0!1+;!1,:|600;$L;R!1+@1$regs;R!2'902vd$r;R1$_H;R!3'a[1#1'`U$_H0;R!1'a\!3'a[1#2#4!2,^72!2'J#4#3!3'b0#2#1#1").
Qed.
Lemma keeps_but_trans : forall L r1 r2 r3, keeps_but L r1 r2 -> keeps_but L r2 r3 -> keeps_but L r1 r3.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S40!1,:|21;!1+;0!1+;!1,:|600;!2'902$L;R!1+@1$r1;R3$r2;R3$r3;R3$A;R!3'b0#4#3#2$B;R!3'b0#5#3#2vd$r;R1$Hr;R!3'a[1#1'`U$HL;R!1'a\!3'a[1#2#8!6'_52!2'J#7#3$b;R2!3+?2#1!2'J#9#4!3#5#3#2#1!2'J#6#3!3#4#3#2#1!3'b0#6#5#3").
Qed.
Lemma keeps_but_upd : forall L regs regs' (rd : reg) v,
  keeps_but L regs regs' -> (In rd L \/ ~ In rd callee_saved) -> keeps_but L regs (regupd regs' rd v).
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S80!1,:|21;!1+;0!1+;!1,:|600;!2'902!3'a[1#1'`U!3+?1#3#7!3'a[1#:#=!1'a\!3'a[1#:'`U$L;R!1+@1$regs;R3$regs';R3$rd;R1$v;R2$K;R!3'b0#5#4#3$Hrd;R!2+2!3'a[1#3#6!1'a\!3'a[1#3'`Uvd$r;R1$Hr;R4$HL;R!1'a\!3'a[1#2#9!6'_52!2'J#8#3$b;R2!3+?2#1!2'J#:#4!3#5#3#2#1!2'J!3'^F#8#7#6#3!5'b1#8#7#6#3vd$H;R5!8'_51#8$r;R1%Hr;R4%HL;R!1'a\!3'a[1#2#=+^<$Hr;R!3'a[1#8'`U$HL;R!1'a\!3'a[1#9#<!6'^D67+^<$~R6!1$Hrd;R!3'a[1#;#>!1#3#1#1$~R7!1$Hrd;R!1'a\!3'a[1#;'`U!1#1#4#1#7#4#1#3#2!1'a\5!3'b0#7#6!3'^F#5#4#3").
Qed.
Lemma keeps_but_cs : forall L regs regs', keeps_cs regs regs' -> keeps_but L regs regs'.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S30!1,:|21;!1+;0!2'90!1+;!1,:|600;$L;R!1+@1$regs;R2$regs';R2$K;R!2'R#2#1vd$r;R1$Hr;R!3'a[1#1'`U$_H;R!1'a\!3'a[1#2#6!2#4#3#2!3'b0#4#3#2").
Qed.
Ltac solve_keeps_but :=
  repeat (apply keeps_but_upd; [| first [left; cbv; tauto | right; not_kept] ]);
  first [apply keeps_but_refl | assumption | apply keeps_but_cs; assumption].
